<?php
class PlanillaAjusteModel{private $db;function __construct(PDO $db){$this->db=$db;}private function concepto(string $naturaleza):int{$n=$naturaleza==='BONIFICACION'?'INGRESO':'DESCUENTO';$q=$this->db->prepare("SELECT id_concepto_pago FROM conceptos_pago WHERE nombre='Ajuste manual' AND naturaleza=? AND tipo='MANUAL' LIMIT 1");$q->execute([$n]);if($id=$q->fetchColumn())return(int)$id;$this->db->prepare("INSERT INTO conceptos_pago(nombre,naturaleza,tipo,estado) VALUES('Ajuste manual',?,'MANUAL','ACTIVO')")->execute([$n]);return(int)$this->db->lastInsertId();}function guardar(array $d,int $usuario):void{$detalle=(int)($d['id_planilla_detalle']??0);$naturaleza=$d['naturaleza']??'';$importe=round((float)($d['importe']??0),2);$motivo=trim($d['motivo']??'');if(!$detalle||!in_array($naturaleza,['BONIFICACION','DESCUENTO'],true)||$importe<=0||strlen($motivo)<3)throw new InvalidArgumentException('Complete tipo, importe y motivo del ajuste.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT pd.*,pp.estado periodo_estado FROM planilla_detalles pd JOIN periodos_pago pp ON pp.id_periodo_pago=pd.id_periodo_pago WHERE pd.id_planilla_detalle=? FOR UPDATE");$q->execute([$detalle]);$pd=$q->fetch();if(!$pd||$pd['periodo_estado']!=='CALCULADO')throw new RuntimeException('Solo se pueden ajustar borradores calculados.');$signo=$naturaleza==='BONIFICACION'?1:-1;$this->db->prepare('INSERT INTO planilla_detalle_conceptos(id_planilla_detalle,id_concepto_pago,id_regla,cantidad,importe,explicacion) VALUES(?,?,NULL,1,?,?)')->execute([$detalle,$this->concepto($naturaleza),$signo*$importe,json_encode(['motivo'=>$motivo,'manual'=>true,'usuario'=>$usuario])]);$concepto=(int)$this->db->lastInsertId();$this->db->prepare("INSERT INTO planilla_ajustes(id_planilla_detalle,id_detalle_concepto,naturaleza,importe,motivo,registrado_por,estado) VALUES(?,?,?,?,?,?,'ACTIVO')")->execute([$detalle,$concepto,$naturaleza,$importe,$motivo,$usuario]);if($naturaleza==='BONIFICACION')$this->db->prepare('UPDATE planilla_detalles SET bonificaciones=bonificaciones+?,monto_pagar=monto_pagar+? WHERE id_planilla_detalle=?')->execute([$importe,$importe,$detalle]);else $this->db->prepare('UPDATE planilla_detalles SET descuentos=descuentos+?,monto_pagar=GREATEST(0,monto_pagar-?) WHERE id_planilla_detalle=?')->execute([$importe,$importe,$detalle]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}function anular(int $id,string $motivo,int $usuario):int{$motivo=trim($motivo);if(!$id||strlen($motivo)<3)throw new InvalidArgumentException('Indique el motivo de anulación.');$this->db->beginTransaction();try{$q=$this->db->prepare("SELECT a.*,pd.id_periodo_pago,pp.estado periodo_estado FROM planilla_ajustes a JOIN planilla_detalles pd ON pd.id_planilla_detalle=a.id_planilla_detalle JOIN periodos_pago pp ON pp.id_periodo_pago=pd.id_periodo_pago WHERE a.id_ajuste=? FOR UPDATE");$q->execute([$id]);$a=$q->fetch();if(!$a||$a['estado']!=='ACTIVO'||$a['periodo_estado']!=='CALCULADO')throw new RuntimeException('El ajuste no puede anularse.');$this->db->prepare('DELETE FROM planilla_detalle_conceptos WHERE id_detalle_concepto=?')->execute([$a['id_detalle_concepto']]);$this->db->prepare("UPDATE planilla_ajustes SET estado='ANULADO',anulado_por=?,anulado_en=NOW(),motivo_anulacion=? WHERE id_ajuste=?")->execute([$usuario,$motivo,$id]);if($a['naturaleza']==='BONIFICACION')$this->db->prepare('UPDATE planilla_detalles SET bonificaciones=GREATEST(0,bonificaciones-?),monto_pagar=GREATEST(0,monto_pagar-?) WHERE id_planilla_detalle=?')->execute([$a['importe'],$a['importe'],$a['id_planilla_detalle']]);else $this->db->prepare('UPDATE planilla_detalles SET descuentos=GREATEST(0,descuentos-?),monto_pagar=monto_pagar+? WHERE id_planilla_detalle=?')->execute([$a['importe'],$a['importe'],$a['id_planilla_detalle']]);$this->db->commit();return(int)$a['id_periodo_pago'];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}}
